import iconv from "iconv-lite";
import { ACadVersion, Insert, MText, TextEntity, type CadDocument, type Entity } from "@node-projects/acad-ts";

import { isUtf8EraVersion } from "./version";

/**
 * Workaround for a real acad-ts bug (see README "Known acad-ts gaps" #3):
 * text bytes are decoded as windows-1252 *regardless of the file's actual
 * encoding* -- verified empirically by round-tripping acad-ts's own output
 * back through windows-1252 and recovering the exact original DXF bytes,
 * for both an R2018/AC1032 UTF-8 fixture and an R2000/$DWGCODEPAGE=ANSI_949
 * (cp949) fixture. This module reverses that: re-encode the string acad-ts
 * gave us as windows-1252 to recover the original bytes, then decode those
 * bytes with the *real* target encoding (UTF-8 for R2007+/AC1021+, else
 * `$DWGCODEPAGE`).
 *
 * This is deliberately narrow: it does not patch acad-ts, only this
 * package's own read path, and only text-bearing fields (TEXT/MTEXT/ATTRIB
 * values, layer names, block names). If the round trip produces a
 * replacement character, the fix is rejected and the original (possibly
 * still wrong) string is kept -- never make already-plausible text worse.
 */

/** `CadUtils.CodePage` numeric values -> the iconv-lite encoding that reads them. */
const CODEPAGE_NUMBER_TO_ICONV: Readonly<Record<number, string>> = {
  1252: "windows-1252",
  1250: "windows-1250",
  1251: "windows-1251",
  1253: "windows-1253",
  1254: "windows-1254",
  1255: "windows-1255",
  1256: "windows-1256",
  1257: "windows-1257",
  1258: "windows-1258",
  874: "windows-874",
  949: "cp949",
  932: "shift_jis",
  936: "gbk",
  950: "big5",
  866: "cp866",
  20127: "ascii",
  28591: "iso-8859-1",
  28592: "iso-8859-2",
};

function targetEncodingFor(version: ACadVersion, codePage: string): string {
  if (isUtf8EraVersion(version)) return "utf-8";
  const match = /(\d+)/.exec(codePage);
  const num = match ? Number(match[1]) : NaN;
  return CODEPAGE_NUMBER_TO_ICONV[num] ?? "windows-1252";
}

/**
 * Windows-1252's 0x80-0x9F block, as acad-ts's decoder actually produces it
 * (verified with a synthetic round trip, see README "Known acad-ts gaps"
 * #3): defined CP1252 code points map per the standard table, and the 5
 * bytes CP1252 itself leaves undefined (0x81, 0x8D, 0x8F, 0x90, 0x9D) pass
 * straight through as their own byte value, Latin-1-style, rather than
 * erroring. `iconv-lite`'s own windows-1252 *encoder* does not reproduce
 * this (it maps all five of those code points to `?`), so those five have
 * to be special-cased here instead of trusting `iconv.encode(s,
 * "windows-1252")` for the reverse step below. Every other byte value
 * (0x00-0x7F, 0xA0-0xFF) is Latin-1-identity in both CP1252 and this
 * decoder, so no table entry is needed for them.
 */
const CP1252_HIGH_BYTE_TO_CODEPOINT: ReadonlyMap<number, number> = new Map([
  [0x80, 0x20ac],
  [0x81, 0x81],
  [0x82, 0x201a],
  [0x83, 0x192],
  [0x84, 0x201e],
  [0x85, 0x2026],
  [0x86, 0x2020],
  [0x87, 0x2021],
  [0x88, 0x2c6],
  [0x89, 0x2030],
  [0x8a, 0x160],
  [0x8b, 0x2039],
  [0x8c, 0x152],
  [0x8d, 0x8d],
  [0x8e, 0x17d],
  [0x8f, 0x8f],
  [0x90, 0x90],
  [0x91, 0x2018],
  [0x92, 0x2019],
  [0x93, 0x201c],
  [0x94, 0x201d],
  [0x95, 0x2022],
  [0x96, 0x2013],
  [0x97, 0x2014],
  [0x98, 0x2dc],
  [0x99, 0x2122],
  [0x9a, 0x161],
  [0x9b, 0x203a],
  [0x9c, 0x153],
  [0x9d, 0x9d],
  [0x9e, 0x17e],
  [0x9f, 0x178],
]);

const CODEPOINT_TO_CP1252_HIGH_BYTE: ReadonlyMap<number, number> = new Map(
  [...CP1252_HIGH_BYTE_TO_CODEPOINT].map(([byte, codepoint]) => [codepoint, byte])
);

/** Reverses acad-ts's forced windows-1252-shaped decode for one code point, or `null` if it never came from a single byte this way. */
function codePointToOriginalByte(codePoint: number): number | null {
  if (codePoint <= 0x7f) return codePoint;
  if (codePoint >= 0xa0 && codePoint <= 0xff) return codePoint;
  const byte = CODEPOINT_TO_CP1252_HIGH_BYTE.get(codePoint);
  return byte ?? null;
}

function fixString(raw: string, targetEncoding: string): string {
  // Pure ASCII has nothing to fix.
  // eslint-disable-next-line no-control-regex
  if (!/[^�-]/.test(raw)) return raw;
  const bytes: number[] = [];
  for (const char of raw) {
    const codePoint = char.codePointAt(0) ?? 0;
    const byte = codePointToOriginalByte(codePoint);
    if (byte === null) return raw; // not something this decoder produced; leave alone
    bytes.push(byte);
  }
  try {
    const fixed = iconv.decode(Buffer.from(bytes), targetEncoding);
    if (fixed.includes("�")) return raw;
    return fixed;
  } catch {
    return raw;
  }
}

function fixEntityText(entity: Entity, targetEncoding: string): void {
  if (entity instanceof MText) {
    const fixed = fixString(entity.value, targetEncoding);
    if (fixed !== entity.value) entity.value = fixed;
  } else if (entity instanceof TextEntity) {
    // TextEntity covers TEXT, and (via AttributeBase) ATTRIB/ATTDEF.
    const fixed = fixString(entity.value, targetEncoding);
    if (fixed !== entity.value) entity.value = fixed;
  }
  if (entity instanceof Insert) {
    for (const attribute of entity.attributes) fixEntityText(attribute, targetEncoding);
  }
}

/**
 * Mutates `doc` in place: fixes TEXT/MTEXT/ATTRIB/ATTDEF values, layer
 * names, and block names that acad-ts mis-decoded. Safe to call
 * unconditionally -- when the target encoding is windows-1252 itself (the
 * common case: `$DWGCODEPAGE`/`$ACADVER` say the file already is
 * windows-1252-ish, e.g. F01/F02/F06...), the encode/decode round trip is
 * the identity and nothing changes.
 */
export function fixDocumentTextEncoding(doc: CadDocument): void {
  if (!doc.header) return;
  const targetEncoding = targetEncodingFor(doc.header.version, doc.header.codePage);
  if (targetEncoding === "windows-1252") return;

  if (doc.layers) {
    for (const layer of doc.layers) {
      const fixed = fixString(layer.name, targetEncoding);
      // Renaming a table entry to its own unchanged name can still throw in
      // acad-ts (observed: the reserved default layer "0" rejects even a
      // same-value re-set) -- only touch entries that actually changed.
      if (fixed !== layer.name) layer.name = fixed;
    }
  }
  if (doc.blockRecords) {
    for (const blockRecord of doc.blockRecords) {
      const fixedName = fixString(blockRecord.name, targetEncoding);
      if (fixedName !== blockRecord.name) blockRecord.name = fixedName;
      for (const entity of blockRecord.entities) fixEntityText(entity, targetEncoding);
    }
  }
}
