import {
  Hatch,
  Insert,
  MText,
  ProxyEntity,
  TextEntity,
  UnknownEntity,
  XYZ,
  type BoundingBox,
  type CadDocument,
  type Entity,
} from "@node-projects/acad-ts";
import type { LayerStatsDocument } from "@halo-cad/schema";

import type { DropEntry } from "../drops";

import { LENGTH_TYPES, statsTypeKey } from "./entity-types";
import { hatchArea } from "./hatch-area";
import { entityLength } from "./length";
import { aggregateTextHash, normalizeText } from "./text";
import { walkSpaceEntities } from "./walk";

type Aggregate = LayerStatsDocument["totals"];

interface BucketAccumulator {
  layer: string;
  space: string;
  entityCount: number;
  countByType: Map<string, number>;
  lengthSum: number;
  hatchAreaSum: number;
  texts: string[];
  insertByBlock: Map<string, number>;
  bboxMin: XYZ | null;
  bboxMax: XYZ | null;
}

function newAccumulator(layer: string, space: string): BucketAccumulator {
  return {
    layer,
    space,
    entityCount: 0,
    countByType: new Map(),
    lengthSum: 0,
    hatchAreaSum: 0,
    texts: [],
    insertByBlock: new Map(),
    bboxMin: null,
    bboxMax: null,
  };
}

function bucketFor(buckets: Map<string, BucketAccumulator>, space: string, layer: string): BucketAccumulator {
  const key = `${space}�${layer}`;
  let bucket = buckets.get(key);
  if (!bucket) {
    bucket = newAccumulator(layer, space);
    buckets.set(key, bucket);
  }
  return bucket;
}

function hex(handle: number): string {
  return handle.toString(16).toUpperCase();
}

function unionBBox(acc: BucketAccumulator, entity: Entity, space: string, drops: DropEntry[]): void {
  let bb: BoundingBox | null;
  try {
    bb = entity.getBoundingBox();
  } catch (err) {
    // acad-ts's Polyline2D/Polyline3D.getBoundingBox() can throw (observed:
    // "Cannot read properties of undefined (reading 'x')" inside
    // PolylineExtensions._toXYZ) when the polyline's SEQEND terminator ends
    // up as a plain element of `vertices` alongside the real Vertex2D/3D
    // objects -- the same SeqendCollection quirk worked around in walk.ts
    // for Insert.attributes, but here it is *inside* acad-ts's own
    // getBoundingBox(), not something a caller can filter first. bbox is an
    // optional field (packages/schema/src/stats/layer-stats.schema.json), so
    // this entity is simply left out of the union rather than failing the
    // whole `stats` run; the drop makes the gap visible.
    drops.push({
      reason: "acad-ts-unsupported",
      message: `entity.getBoundingBox() threw (${err instanceof Error ? err.message : String(err)}); excluded from bbox`,
      entityType: entity.objectName || undefined,
      handle: hex(entity.handle),
      space,
      layer: entity.layer.name,
    });
    return;
  }
  if (!bb) return;
  const { min, max } = bb;
  if (![min.x, min.y, min.z, max.x, max.y, max.z].every(Number.isFinite)) return;
  if (!acc.bboxMin || !acc.bboxMax) {
    acc.bboxMin = new XYZ(min.x, min.y, min.z);
    acc.bboxMax = new XYZ(max.x, max.y, max.z);
    return;
  }
  acc.bboxMin.x = Math.min(acc.bboxMin.x, min.x);
  acc.bboxMin.y = Math.min(acc.bboxMin.y, min.y);
  acc.bboxMin.z = Math.min(acc.bboxMin.z, min.z);
  acc.bboxMax.x = Math.max(acc.bboxMax.x, max.x);
  acc.bboxMax.y = Math.max(acc.bboxMax.y, max.y);
  acc.bboxMax.z = Math.max(acc.bboxMax.z, max.z);
}

/** TEXT.value / MText.value (raw contents, control codes intact) / ATTRIB.value. */
function textValueOf(entity: Entity): string {
  if (entity instanceof MText) return entity.value;
  if (entity instanceof TextEntity) return entity.value; // covers TEXT and ATTRIB (AttributeEntity extends TextEntity)
  return "";
}

function processEntity(entity: Entity, space: string, buckets: Map<string, BucketAccumulator>, drops: DropEntry[]): void {
  const isUnknown = entity instanceof UnknownEntity;
  const isProxy = entity instanceof ProxyEntity;
  // count_by_type keys are raw DXF record names (see entity-types.ts). For
  // UnknownEntity, `objectName` is whatever real class name acad-ts managed
  // to resolve from the DXF class table (possibly ""); for ProxyEntity it is
  // always the literal token "ACAD_PROXY_ENTITY". Either way it still has to
  // pass the schema's key pattern.
  const normalized = statsTypeKey(entity.objectName || "ACAD_PROXY_ENTITY");
  const layerName = entity.layer.name;

  if (normalized === null) {
    drops.push({
      reason: "stats-schema-unsupported-type",
      message: `entity type '${entity.objectName}' does not fit the LayerStatsDocument count_by_type key pattern; excluded from stats`,
      entityType: entity.objectName,
      handle: hex(entity.handle),
      space,
      layer: layerName,
    });
    return;
  }

  if (isUnknown || isProxy) {
    drops.push({
      reason: "acad-ts-unsupported",
      message: isUnknown
        ? `acad-ts could not fully resolve this entity to a known class (read as UnknownEntity); counted under '${normalized}'`
        : `entity persisted only as proxy graphics (ACAD_PROXY_ENTITY); counted under '${normalized}'`,
      entityType: entity.objectName || undefined,
      handle: hex(entity.handle),
      space,
      layer: layerName,
    });
  }

  const bucket = bucketFor(buckets, space, layerName);

  // stats-definition.md count_by_type: "ATTRIB·SEQEND·VERTEX는 세지 않는다
  // (소유 엔티티에 속함)" -- ATTRIB is owned by its INSERT, so it never
  // becomes a top-level count_by_type/entity_count contribution, unlike
  // TEXT/MTEXT. It still gets its own bucket (by its own layer, per
  // text_count's "ATTRIB 자신의 레이어에 귀속") purely so its text is
  // discoverable via that bucket's text_count/text_hash.
  if (normalized === "ATTRIB") {
    bucket.texts.push(normalizeText(textValueOf(entity)));
    return;
  }

  bucket.entityCount += 1;
  bucket.countByType.set(normalized, (bucket.countByType.get(normalized) ?? 0) + 1);

  if (LENGTH_TYPES.has(normalized)) bucket.lengthSum += entityLength(entity);
  if (normalized === "HATCH" && entity instanceof Hatch) bucket.hatchAreaSum += hatchArea(entity);
  if (normalized === "TEXT" || normalized === "MTEXT") {
    bucket.texts.push(normalizeText(textValueOf(entity)));
  }
  if (normalized === "INSERT" && entity instanceof Insert) {
    let blockName = entity.block?.name;
    if (blockName == null || blockName === "") {
      blockName = "<unresolved>";
      drops.push({
        reason: "acad-ts-unsupported",
        message: "INSERT references an unresolved block record",
        handle: hex(entity.handle),
        space,
        layer: layerName,
      });
    } else {
      blockName = blockName.normalize("NFC");
    }
    bucket.insertByBlock.set(blockName, (bucket.insertByBlock.get(blockName) ?? 0) + 1);
  }

  unionBBox(bucket, entity, space, drops);
}

function round6(n: number): number {
  return Math.round(n * 1e6) / 1e6;
}

function finalizeAggregate(acc: BucketAccumulator): Aggregate {
  const countByType: Record<string, number> = {};
  for (const [type, count] of [...acc.countByType].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
    countByType[type] = count;
  }
  const insertByBlock: Record<string, number> = {};
  for (const [block, count] of [...acc.insertByBlock].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
    insertByBlock[block] = count;
  }
  const aggregate: Aggregate = {
    entity_count: acc.entityCount,
    count_by_type: countByType,
    length_sum_mm: round6(acc.lengthSum),
    hatch_area_sum_mm2: round6(acc.hatchAreaSum),
    text_count: acc.texts.length,
    text_hash: aggregateTextHash(acc.texts),
    insert_by_block: insertByBlock,
  };
  if (acc.bboxMin && acc.bboxMax) {
    aggregate.bbox = {
      min: [acc.bboxMin.x, acc.bboxMin.y, acc.bboxMin.z],
      max: [acc.bboxMax.x, acc.bboxMax.y, acc.bboxMax.z],
    };
  }
  return aggregate;
}

function mergeAccumulators(accumulators: Iterable<BucketAccumulator>): BucketAccumulator {
  const total = newAccumulator("", "");
  for (const acc of accumulators) {
    total.entityCount += acc.entityCount;
    for (const [type, count] of acc.countByType) total.countByType.set(type, (total.countByType.get(type) ?? 0) + count);
    total.lengthSum += acc.lengthSum;
    total.hatchAreaSum += acc.hatchAreaSum;
    total.texts.push(...acc.texts);
    for (const [block, count] of acc.insertByBlock) {
      total.insertByBlock.set(block, (total.insertByBlock.get(block) ?? 0) + count);
    }
    if (acc.bboxMin && acc.bboxMax) {
      if (!total.bboxMin || !total.bboxMax) {
        total.bboxMin = new XYZ(acc.bboxMin.x, acc.bboxMin.y, acc.bboxMin.z);
        total.bboxMax = new XYZ(acc.bboxMax.x, acc.bboxMax.y, acc.bboxMax.z);
      } else {
        total.bboxMin.x = Math.min(total.bboxMin.x, acc.bboxMin.x);
        total.bboxMin.y = Math.min(total.bboxMin.y, acc.bboxMin.y);
        total.bboxMin.z = Math.min(total.bboxMin.z, acc.bboxMin.z);
        total.bboxMax.x = Math.max(total.bboxMax.x, acc.bboxMax.x);
        total.bboxMax.y = Math.max(total.bboxMax.y, acc.bboxMax.y);
        total.bboxMax.z = Math.max(total.bboxMax.z, acc.bboxMax.z);
      }
    }
  }
  return total;
}

function compareBuckets(a: BucketAccumulator, b: BucketAccumulator): number {
  if (a.layer !== b.layer) return a.layer < b.layer ? -1 : 1;
  if (a.space !== b.space) return a.space < b.space ? -1 : 1;
  return 0;
}

export interface BuildStatsResult {
  buckets: LayerStatsDocument["buckets"];
  totals: Aggregate;
  drops: DropEntry[];
}

/**
 * Builds the bucket list and totals of a `LayerStatsDocument` from an
 * already-read `CadDocument`, per docs/contracts/stats-definition.md. The
 * caller (commands/stats.ts) adds `schema_version`, `file_sha256`, and
 * `producer`, then validates the assembled document with
 * `@halo-cad/schema`'s `validateLayerStats`.
 */
export function buildStats(doc: CadDocument): BuildStatsResult {
  if (!doc.modelSpace) throw new Error("document has no model space");
  const buckets = new Map<string, BucketAccumulator>();
  const drops: DropEntry[] = [];
  for (const { entity, space } of walkSpaceEntities(doc)) {
    processEntity(entity, space, buckets, drops);
  }
  const sortedBuckets = [...buckets.values()].sort(compareBuckets);
  return {
    buckets: sortedBuckets.map((acc) => ({ layer: acc.layer, space: acc.space, aggregate: finalizeAggregate(acc) })),
    totals: finalizeAggregate(mergeAccumulators(buckets.values())),
    drops,
  };
}
